import { createTemplateContext } from "./template-context";
import { TemplatePickerPanel } from "./template-picker";

export function mountEditorPersonalization(session: EditorSession) {
  const context = createTemplateContext(session.businessContext);
  // This callback is registered for this editor session and dies with it.
  session.extensions.register("template-personalization", selectedTemplate => context.forTemplate(selectedTemplate));
  session.panels.register("template-picker", new TemplatePickerPanel(session.extensions));
}

// Shared declaration layer; no provider or state lives here today.
export interface EditorContextProvider {
  forTemplate(selectedTemplate: string): TemplateContext;
}
export interface TemplateContext {
  selectedTemplate: string;
  businessContext: string;
}

export class TemplatePickerPanel {
  constructor(private readonly extensions: EditorExtensions) {}
  personalize(selectedTemplate: string) {
    return this.extensions.call("template-personalization", selectedTemplate);
  }
}
